create table if not exists public.resource_attachments (
  id uuid primary key default gen_random_uuid(),
  resource_id uuid not null references public.resources(id) on delete cascade,
  storage_provider text not null check (storage_provider in ('supabase', 'cloudinary')),
  storage_key text not null,
  filename text not null check (char_length(filename) between 1 and 180),
  mimetype text not null check (char_length(mimetype) between 1 and 180),
  size_bytes bigint not null check (size_bytes between 1 and 10485760),
  uploaded_by uuid references public.users(id) on delete set null,
  created_at timestamptz not null default now()
);

create index if not exists resource_attachments_resource_idx
  on public.resource_attachments (resource_id, created_at);

alter table public.resource_attachments enable row level security;
grant all privileges on table public.resource_attachments to service_role;
drop policy if exists service_role_only on public.resource_attachments;
create policy service_role_only on public.resource_attachments
  for all to service_role using (true) with check (true);

insert into public.resources (title, slug, excerpt, body, category, tags, status, data, published_at)
values
  ($title$Before you send your SOP for review$title$, $slug$sop-review-checklist$slug$, $excerpt$Check the prompt, programme fit and evidence in your draft before asking for feedback.$excerpt$, $body$$body$, $category$Graduate admissions$category$, array[$tag$checklist$tag$, $tag$graduate$tag$, $tag$admissions$tag$], 'published', $data${"format":"Checklist","resource_schema":{"sections":[{"id":"how-to-use-this-checklist","title":"How to use this checklist","content":"Put the official application instructions beside your statement of purpose (SOP). Work through the six checks below. Tick an item only after checking your draft; record anything unresolved in the notes. You can request feedback on an incomplete draft, provided you tell the reviewer what is missing.","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]},{"id":"your-application","title":"Your application","content":"- Programme and institution: `[Write here]`\n- Official programme/application link: `[Paste link]`\n- Deadline, including time zone: `[Write here]`\n- Current draft word count: `[Write here]`\n- Date you checked the instructions: `[Write here]`","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]},{"id":"check-1-are-you-answering-the-actual-question","title":"Check 1: Are you answering the actual question?","content":"Copy the prompt exactly. Include any separate instructions about content, length and format.\n\n**Official prompt:**\n\n`[Paste the full prompt here]`\n\n| What the prompt asks | Where your draft answers it | Change needed |\n|---|---|---|\n| `[First requirement]` | `[Paragraph or passage]` | `[Write here, or None]` |\n| `[Next requirement]` | `[Paragraph or passage]` | `[Write here, or None]` |\n\n- [ ] Every required part has an identifiable answer.\n- [ ] I have checked the word/page limit and file requirements.\n- [ ] I have checked if the programme asks for a separate personal history or other statement.","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]},{"id":"check-2-is-your-study-direction-clear","title":"Check 2: Is your study direction clear?","content":"Answer these questions before judging the wording:\n\n- What work, problem or research question do you want to pursue? `[Write here]`\n- What have you done that brought this interest into focus? `[Write here]`\n- What knowledge, methods or experience do you need next? `[Write here]`\n- How would this degree help you take a plausible next step? `[Write here]`\n\n- [ ] The reader can connect my experience, proposed study and next step.\n- [ ] My plans stay within what I could reasonably do in the role or setting I describe.","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]},{"id":"check-3-have-you-shown-evidence-from-experience","title":"Check 3: Have you shown evidence from experience?","content":"Choose one or two experiences that support your preparation. Coursework, research, paid work, NYSC and volunteering can all be relevant.\n\n| Experience | What you personally did | Result, finding or learning | What it shows |\n|---|---|---|---|\n| `[Write here]` | `[Write here]` | `[Write here]` | `[Relevant preparation]` |\n| `[Write here]` | `[Write here]` | `[Write here]` | `[Relevant preparation]` |\n\n**Fictional example:** “I helped analyse attendance records for an after-school programme. Comparing participation across locations made me want to understand how programme design affects access.” This connects a specific task to a study interest without claiming to have solved the underlying problem.\n\n- [ ] I distinguish my contribution from the team’s work.\n- [ ] My examples explain something the transcript or CV alone would not show.","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]},{"id":"check-4-is-programme-fit-explained","title":"Check 4: Is programme fit explained?","content":"Use current official information. A course name helps only when you explain its relevance.\n\n| Verified programme feature and source | Preparation it would help you develop | Connection to your plans |\n|---|---|---|\n| `[Course, method, research area or other feature + link]` | `[Write here]` | `[Write here]` |\n\n- [ ] I have checked that the feature is currently offered and any access conditions.\n- [ ] I explain why it matters to my learning needs.\n- [ ] I have removed praise that could describe almost any university.","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]},{"id":"check-5-can-you-support-your-claims","title":"Check 5: Can you support your claims?","content":"- [ ] Names, qualifications, dates and responsibilities match my records.\n- [ ] Numbers are accurate, with the period and my contribution clear.\n- [ ] Team outcomes are attributed fairly.\n- [ ] The draft is consistent with my CV and other application answers.\n- [ ] I can explain each example in a conversation.\n\n**Claims or passages to check:** `[Write here]`","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]},{"id":"check-6-have-you-prepared-the-review-brief","title":"Check 6: Have you prepared the review brief?","content":"Send the draft, prompt, word limit, official link and deadline together. Identify the feedback you need rather than asking only if the statement is “good”.\n\n**My questions for the reviewer:**\n\n1. `[For example: Is the reason for further study clear?]`\n2. `[For example: Which example needs more evidence?]`\n3. `[Your question]`\n\n**Known gaps in this draft:** `[Write here]`\n\n**My next action and date:** `[Write here]`\n\n[Discuss a statement review](https://careergrill-website-concept.sannialausa.chatgpt.site/consultation?service=admissions&offer=1)\n\n---","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]}]},"content_source_version":"full-content-2026-10"}$data$::jsonb, now()),
  ($title$What does the scholarship actually cover?$title$, $slug$check-scholarship-funding$slug$, $excerpt$Separate the award’s funding from the costs you will still need to cover.$excerpt$, $body$$body$, $category$Scholarships$category$, array[$tag$checklist$tag$, $tag$scholarships$tag$], 'published', $data${"format":"Checklist","resource_schema":{"sections":[{"id":"how-to-use-this-checklist","title":"How to use this checklist","content":"Use the provider’s current award terms and the institution’s official cost information. Record the source and date for each detail. If coverage is unclear, mark it **Unconfirmed** and write down who can clarify it. A description such as “fully funded” does not replace the detailed terms.","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]},{"id":"award-details","title":"Award details","content":"- Scholarship and provider: `[Write here]`\n- Programme, institution and destination: `[Write here]`\n- Intake and programme duration: `[Write here]`\n- Official award terms: `[Paste link]`\n- Official fee/cost information: `[Paste link]`\n- Date checked: `[Write here]`","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]},{"id":"check-1-tuition-and-compulsory-fees","title":"Check 1: Tuition and compulsory fees","content":"| Cost | Amount and currency | Award coverage | Your share / uncertainty |\n|---|---|---|---|\n| Tuition for the full programme | `[Write here]` | `[Amount, percentage or Unconfirmed]` | `[Write here]` |\n| Compulsory institutional charges | `[Write here]` | `[Write here]` | `[Write here]` |\n| Required research, laboratory or fieldwork costs | `[Write here, or Not applicable]` | `[Write here]` | `[Write here]` |\n\n- [ ] I have checked the correct fee category for my nationality/residence and programme.\n- [ ] I know how many years or terms the funding covers.\n- [ ] I have checked exclusions, fee caps and conditions for continued funding.","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]},{"id":"check-2-living-costs-and-payment-timing","title":"Check 2: Living costs and payment timing","content":"- Stipend amount, currency and payment frequency: `[Write here]`\n- Months covered: `[Write here]`\n- Expected first payment: `[Write here, or Unconfirmed]`\n- Costs due before that payment: `[Write here]`\n\n| Living cost | Period being budgeted | Expected cost | Covered / not covered / unconfirmed |\n|---|---|---|---|\n| Accommodation and utilities | `[Write here]` | `[Amount + currency]` | `[Write here]` |\n| Food and local transport | `[Write here]` | `[Amount + currency]` | `[Write here]` |\n| Other essential costs | `[Write here]` | `[Amount + currency]` | `[Write here]` |\n\n**Illustrative check:** If a programme lasts 12 months but the stipend covers 10, identify how you will cover the remaining two months. Check the actual award schedule before treating this as a funding gap.","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]},{"id":"check-3-travel-immigration-and-arrival-costs","title":"Check 3: Travel, immigration and arrival costs","content":"Check each item against the award terms and the relevant official requirements. Do not assume that a paid tuition fee also covers these costs.\n\n| Item | Paid by award, reimbursed later, self-funded or unconfirmed | When payment is due | Source / question |\n|---|---|---|---|\n| Travel to and from the destination | `[Write here]` | `[Write here]` | `[Write here]` |\n| Visa and required immigration charges | `[Write here]` | `[Write here]` | `[Write here]` |\n| Required health insurance or health charges | `[Write here]` | `[Write here]` | `[Write here]` |\n| Accommodation deposit / initial rent | `[Write here]` | `[Write here]` | `[Write here]` |\n| Document, test or application costs | `[Write here]` | `[Write here]` | `[Write here]` |\n| Dependants’ costs, if relevant | `[Write here]` | `[Write here]` | `[Write here]` |\n\n- [ ] I have separated costs paid directly from costs reimbursed later.\n- [ ] I know which expenses I may need to pay upfront.","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]},{"id":"check-4-admission-and-funding-requirements","title":"Check 4: Admission and funding requirements","content":"| Requirement | Admission requirement | Scholarship requirement | Action needed |\n|---|---|---|---|\n| Qualifications / academic preparation | `[Write here]` | `[Write here]` | `[Write here]` |\n| Tests or language evidence | `[Write here]` | `[Write here]` | `[Write here]` |\n| Offer, nomination or endorsement | `[Write here]` | `[Write here]` | `[Write here]` |\n\n- [ ] I know if admission and funding require separate applications.\n- [ ] I have checked nationality, residence, course and other eligibility restrictions.","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]},{"id":"check-5-deadlines-and-application-routes","title":"Check 5: Deadlines and application routes","content":"| Submission | Official date, time and time zone | Route / person responsible | My earlier target date |\n|---|---|---|---|\n| Programme admission | `[Write here]` | `[Write here]` | `[Write here]` |\n| Scholarship | `[Write here]` | `[Write here]` | `[Write here]` |\n| Nomination / reference, if separate | `[Write here]` | `[Write here]` | `[Write here]` |","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]},{"id":"check-6-conditions-after-an-award","title":"Check 6: Conditions after an award","content":"- [ ] I have read acceptance and enrolment conditions.\n- [ ] I have checked academic progression and funding-renewal requirements.\n- [ ] I have checked restrictions on combining awards or paid work, where stated.\n- [ ] I have read any return, service or repayment conditions.\n- [ ] I have identified the official contact for unanswered questions.\n\n**Known costs I must cover:** `[List amounts, currencies and due dates]`\n\n**Costs or conditions still unconfirmed:** `[Write here]`\n\n**Question to send the provider:** “Could you confirm if `[cost/condition]` is covered, the amount or limit, and when it is paid?”\n\n**My next action and date:** `[Write here]`\n\n[Explore scholarships](https://careergrill-website-concept.sannialausa.chatgpt.site/scholarships)\n\n---","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]}]},"content_source_version":"full-content-2026-10"}$data$::jsonb, now()),
  ($title$Turn your work into CV evidence$title$, $slug$turn-work-into-cv-evidence$slug$, $excerpt$Find your contribution in everyday work, research, volunteering or NYSC experience.$excerpt$, $body$$body$, $category$Career documents$category$, array[$tag$worksheet$tag$, $tag$career$tag$, $tag$documents$tag$], 'published', $data${"format":"Worksheet","resource_schema":{"sections":[{"id":"how-to-use-this-worksheet","title":"How to use this worksheet","content":"Work on one experience at a time. Start with notes or records rather than trying to write an impressive sentence immediately. A useful CV point tells the employer what you did and why it was relevant. Include a number only when you can support it.","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]},{"id":"experience-details","title":"Experience details","content":"- Organisation, project or setting: `[Write here]`\n- Role and dates: `[Write here]`\n- Target role or type of work: `[Write here]`\n- Relevant job requirement and source: `[Paste the requirement and link]`","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]},{"id":"step-1-describe-the-task","title":"Step 1: Describe the task","content":"What needed doing? Who needed it? What made the work difficult or worth doing?\n\n`[Write two or three sentences]`","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]},{"id":"step-2-separate-your-responsibility-from-the-team-s","title":"Step 2: Separate your responsibility from the team’s","content":"- The team was responsible for: `[Write here]`\n- I was personally responsible for: `[Write here]`\n- Decisions I could make: `[Write here]`\n- People I worked with and their roles: `[Write here]`","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]},{"id":"step-3-record-your-actions","title":"Step 3: Record your actions","content":"Use concrete verbs: analysed, drafted, checked, coordinated, designed, reconciled, interviewed or maintained. Choose the verb that accurately describes your work.\n\n| Action you took | Tool, method or decision | Output you produced |\n|---|---|---|\n| `[Write here]` | `[Write here]` | `[Write here]` |\n| `[Write here]` | `[Write here]` | `[Write here]` |","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]},{"id":"step-4-identify-the-outcome","title":"Step 4: Identify the outcome","content":"What changed, became easier or became possible? Your outcome might be a completed deliverable, a corrected record, a finding used in a decision or an agreed process. It does not have to be a percentage increase.\n\n- Outcome I can describe: `[Write here]`\n- Number and period, if verified: `[Write here, or Not available]`\n- What I cannot reasonably attribute to my work: `[Write here]`","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]},{"id":"step-5-check-the-evidence","title":"Step 5: Check the evidence","content":"| Detail or claim | Record, output or person that can confirm it | Any limit on using it publicly? |\n|---|---|---|\n| `[Write here]` | `[Write here]` | `[Confidentiality or permission issue, if any]` |\n\nKeep confidential records private. A CV can describe your contribution without revealing personal data or restricted project information.","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]},{"id":"step-6-connect-the-experience-to-the-target-role","title":"Step 6: Connect the experience to the target role","content":"- Requirement this example supports: `[Write here]`\n- Most relevant action or result: `[Write here]`\n- Detail that can be left out: `[Write here]`\n\n**Working structure:** Action + task or output + useful context + supported outcome. Use the parts you have; do not invent a result to complete the structure.\n\n**Fictional worked example**\n\n- Task: A small NGO needed a reliable attendance report for four workshops.\n- Personal responsibility: Check registration and attendance records, then prepare the summary.\n- Action: Reconciled names in Excel, removed duplicate entries and flagged missing records.\n- Outcome: Produced an attendance summary used in the project report. Records confirmed 76 attendees across the four workshops.\n- CV point: “Reconciled registration and attendance records in Excel for four workshops, producing a verified summary of 76 attendees for the project report.”\n\n**Example without a verified metric:** “Introduced a shared enquiry log and handover notes so the customer-support team could track unresolved requests across shifts.” Use this only if the log was introduced and used as described; it does not claim an unmeasured reduction in response time.","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]},{"id":"draft-and-review-your-cv-point","title":"Draft and review your CV point","content":"**First draft:** `[Write here]`\n\n**Revised version for the target role:** `[Write here]`\n\n- [ ] The action belongs to me.\n- [ ] Any result or number is supported.\n- [ ] The wording makes my contribution clear.\n- [ ] The point supports a requirement of the role.\n- [ ] I can explain the example in an interview.\n\n**Next experience to work on:** `[Write here]`\n\n[Discuss a CV review](https://careergrill-website-concept.sannialausa.chatgpt.site/consultation?service=career&offer=0)\n\n---","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]}]},"content_source_version":"full-content-2026-10"}$data$::jsonb, now()),
  ($title$Plan an application backwards from the deadline$title$, $slug$plan-application-backwards-from-deadline$slug$, $excerpt$Give documents, referees and final checks their own dates in your plan.$excerpt$, $body$$body$, $category$Graduate admissions$category$, array[$tag$worksheet$tag$, $tag$graduate$tag$, $tag$admissions$tag$], 'published', $data${"format":"Worksheet","resource_schema":{"sections":[{"id":"how-to-use-this-worksheet","title":"How to use this worksheet","content":"Complete one copy per opportunity. Confirm the official deadline first, including its time zone, then choose an earlier personal submission target. Work backwards from that target using your actual availability and the lead times other people confirm.","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]},{"id":"step-1-record-the-opportunity-and-official-sources","title":"Step 1: Record the opportunity and official sources","content":"- Programme or award: `[Write here]`\n- Institution / provider: `[Write here]`\n- Application portal and official instructions: `[Paste links]`\n- Date checked: `[Write here]`\n- Admission and funding applications separate? `[Yes / No / To confirm]`","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]},{"id":"step-2-set-the-dates-that-control-the-plan","title":"Step 2: Set the dates that control the plan","content":"| Submission | Official date, time and time zone | Your local equivalent | Personal target |\n|---|---|---|---|\n| Main application | `[Write here]` | `[Write here]` | `[Write here]` |\n| Funding application, if separate | `[Write here]` | `[Write here]` | `[Write here]` |\n| Referee / nomination submission | `[Write here]` | `[Write here]` | `[Write here]` |\n\nCheck the time conversion with a reliable time-zone tool. Do not assume that midnight in the provider’s location means midnight where you are.","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]},{"id":"step-3-list-every-required-document","title":"Step 3: List every required document","content":"Break large tasks into outputs you can finish. For example, “statement” may need research, an outline, a complete draft, feedback and revision.\n\n| Document or task | Current stage | Owner | Needed by | Depends on |\n|---|---|---|---|---|\n| Statement / essays | `[Not started / Notes / Draft / Checked]` | `[Name]` | `[Date]` | `[Research, feedback, etc.]` |\n| CV | `[Write here]` | `[Name]` | `[Date]` | `[Write here]` |\n| Transcript / academic records | `[Write here]` | `[Name / office]` | `[Date]` | `[Write here]` |\n| References | `[Write here]` | `[Names]` | `[Date]` | `[Consent, brief, portal invitation]` |\n| Test / language evidence, if required | `[Write here]` | `[Name]` | `[Date]` | `[Result release / delivery]` |\n| Other required item | `[Write here]` | `[Name]` | `[Date]` | `[Write here]` |","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]},{"id":"step-4-arrange-referees-and-records-early","title":"Step 4: Arrange referees and records early","content":"- Referee agreement requested by: `[Date]`\n- Brief and supporting materials sent by: `[Date]`\n- Reminder date agreed with each referee: `[Write here]`\n- Transcript request submitted by: `[Date]`\n- Issuing office’s expected processing time: `[Confirmed time / To confirm]`\n- Translation or certification required? `[Requirement + source / Not applicable]`\n- Backup action if something is delayed: `[Write here]`","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]},{"id":"step-5-schedule-drafting-and-feedback","title":"Step 5: Schedule drafting and feedback","content":"| Milestone | Date you will finish | Person who needs to respond | Confirmed turnaround / dependency |\n|---|---|---|---|\n| Programme research and evidence notes | `[Date]` | `[Name / Not applicable]` | `[Write here]` |\n| Complete first draft | `[Date]` | `[Name]` | `[Write here]` |\n| Feedback received | `[Date]` | `[Name]` | `[Write here]` |\n| Revision completed | `[Date]` | `[Name / Not applicable]` | `[Write here]` |\n| Final proofread and upload | `[Date]` | `[Name]` | `[Write here]` |\n\nAsk a reviewer about availability before building their response into the plan. If you are booking paid support, use its agreed delivery dates and leave time for the work you must do between rounds.\n\n**Illustrative scheduling check:** If your reviewer can respond only after your personal submission target, the plan needs to change. You might bring the draft date forward, agree another reviewer or adjust the target while remaining within the official deadline.","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]},{"id":"step-6-reserve-time-for-final-checks","title":"Step 6: Reserve time for final checks","content":"- [ ] I can access the portal and understand its required fields.\n- [ ] File names, formats and sizes meet the instructions.\n- [ ] Essays answer the correct prompts and meet the limits.\n- [ ] Names, dates and qualifications are consistent across documents.\n- [ ] Required references and records have been received, or their separate deadlines are recorded.\n- [ ] I have allowed time for payment or submission problems where applicable.\n- [ ] I know where to find the submission confirmation.","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]},{"id":"your-next-three-actions","title":"Your next three actions","content":"| Action | Date | What will show it is complete? |\n|---|---|---|\n| `[Write here]` | `[Date]` | `[Write here]` |\n| `[Write here]` | `[Date]` | `[Write here]` |\n| `[Write here]` | `[Date]` | `[Write here]` |\n\n**Unresolved question and who to ask:** `[Write here]`\n\n**After submission:** Save the confirmation, record outstanding items and check the portal for further instructions.\n\n---","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]}]},"content_source_version":"full-content-2026-10"}$data$::jsonb, now()),
  ($title$Plan your scholarship motivation letter$title$, $slug$plan-scholarship-motivation-letter$slug$, $excerpt$Map your study goal and experience to the scholarship’s actual questions.$excerpt$, $body$$body$, $category$Scholarships$category$, array[$tag$template$tag$, $tag$scholarships$tag$], 'published', $data${"format":"Template","resource_schema":{"sections":[{"id":"how-to-use-this-template","title":"How to use this template","content":"Complete the planning fields before drafting. These headings organise your thinking; they are not headings you must submit in the letter. Some scholarships use separate essay questions instead of one letter. Follow the requested format and use only the parts relevant to that task.","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]},{"id":"part-1-prompt-and-selection-criteria","title":"Part 1: Prompt and selection criteria","content":"- Scholarship and institution: `[Write here]`\n- Programme or proposed study: `[Write here]`\n- Official instructions and criteria: `[Paste links]`\n- Word/page limit and deadline: `[Write here]`\n- Date checked: `[Write here]`\n\n**Exact question or prompt:**\n\n`[Paste here]`\n\n| What the provider asks you to demonstrate | Evidence or explanation you could use | Anything missing? |\n|---|---|---|\n| `[Copy a criterion or requirement]` | `[Write here]` | `[Write here]` |\n| `[Copy the next criterion]` | `[Write here]` | `[Write here]` |\n| `[Copy the next criterion]` | `[Write here]` | `[Write here]` |","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]},{"id":"part-2-why-this-next-step","title":"Part 2: Why this next step?","content":"Answer in notes first:\n\n- The issue, work or question I want to pursue: `[Write here]`\n- How my experience brought me to it: `[Write here]`\n- What I can already do: `[Write here]`\n- What I need to learn or practise next: `[Write here]`\n- Why this is an appropriate time for further study: `[Write here]`\n\n**My central reason for applying, in two sentences:**\n\n`[Write here]`","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]},{"id":"part-3-an-experience-that-supports-your-direction","title":"Part 3: An experience that supports your direction","content":"Duplicate this block if the prompt calls for another example.\n\n- Context: `[What was happening?]`\n- My responsibility: `[What was I expected to do?]`\n- My action or decision: `[What did I personally do, and why?]`\n- Outcome or learning: `[What happened or what did I discover?]`\n- Evidence I can check: `[Record, output, feedback or other source]`\n- Connection to the scholarship criterion: `[Write here]`\n- Connection to the study goal: `[Write here]`\n\n**Fictional planning example:** An applicant helped interview small-business owners for a research project. Several struggled to explain their borrowing costs. The applicant’s task was to organise and code the interview notes, not design lending policy. That work could support an interest in financial literacy or consumer finance if the applicant can explain what they observed and which further skills they need.","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]},{"id":"part-4-programme-and-scholarship-fit","title":"Part 4: Programme and scholarship fit","content":"Explain fit separately. The programme provides learning opportunities; the scholarship has its own purpose and selection criteria.\n\n| Verified feature or criterion | Why it matters to your plan | Source |\n|---|---|---|\n| `[Programme course, method or research opportunity]` | `[Specific learning need]` | `[Official link]` |\n| `[Scholarship criterion or opportunity]` | `[Your evidence or reason]` | `[Official link]` |\n\n**If the prompt asks about financial circumstances:** Explain your relevant situation factually, the barrier it creates and what the award would make possible. Include the detail requested without adding private information that the application does not need.\n\n`[Notes, or Not requested]`","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]},{"id":"part-5-a-realistic-use-for-the-learning","title":"Part 5: A realistic use for the learning","content":"- Work or setting where I could apply it: `[Write here]`\n- A plausible role or responsibility: `[Write here]`\n- First action I could take: `[Write here]`\n- People or organisations I would need to work with: `[Write here]`\n- Limits, resources or decisions outside my control: `[Write here]`\n\n**My proposed use of the learning:**\n\n`[Write two or three sentences]`","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]},{"id":"part-6-build-the-draft-and-revise","title":"Part 6: Build the draft and revise","content":"Use the prompt to choose your order. This is a planning option, not a compulsory structure:\n\n| Draft section | Job it needs to do | Your notes / intended space |\n|---|---|---|\n| Opening | Establish the reason for this application | `[Write here]` |\n| Evidence | Demonstrate relevant preparation through selected experience | `[Write here]` |\n| Fit | Connect verified programme features and award criteria to your needs | `[Write here]` |\n| Use afterwards | Explain a credible next step | `[Write here]` |\n| Closing | Finish the argument and answer anything still missing | `[Write here]` |\n\n**Draft text:**\n\n`[Write your draft here, or link to your working document]`\n\n- [ ] Every part of the prompt is answered.\n- [ ] Examples show my actions rather than just describing my qualities.\n- [ ] Programme and award details are current and accurate.\n- [ ] Future plans are specific and proportionate to my likely role.\n- [ ] The letter is consistent with my CV and other answers.\n- [ ] I have followed the provider’s rules on authorship and assistance.\n\n**What remains unanswered?** `[Write here]`\n\n**Which claim needs checking?** `[Write here]`\n\n**What can I cut without losing the argument?** `[Write here]`\n\n[Discuss scholarship essay support](https://careergrill-website-concept.sannialausa.chatgpt.site/consultation?service=scholarships&offer=0)\n\n---","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]}]},"content_source_version":"full-content-2026-10"}$data$::jsonb, now()),
  ($title$Match your experience to a fellowship’s criteria$title$, $slug$match-experience-fellowship-criteria$slug$, $excerpt$Build examples around the criteria before you start writing the application.$excerpt$, $body$$body$, $category$Fellowships$category$, array[$tag$worksheet$tag$, $tag$fellowships$tag$], 'published', $data${"format":"Worksheet","resource_schema":{"sections":[{"id":"how-to-use-this-worksheet","title":"How to use this worksheet","content":"Read the current fellowship call and distinguish eligibility conditions from qualities assessed during selection. Meeting an eligibility condition does not, by itself, demonstrate a selection criterion. Complete an evidence card for each criterion the application asks you to address.","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]},{"id":"fellowship-details","title":"Fellowship details","content":"- Fellowship and provider: `[Write here]`\n- Official call and selection criteria: `[Paste links]`\n- Application questions and word limits: `[Copy or link]`\n- Deadline and time zone: `[Write here]`\n- Date checked: `[Write here]`\n- Eligibility questions still unresolved: `[Write here]`","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]},{"id":"step-1-map-the-criteria","title":"Step 1: Map the criteria","content":"| Criterion in the provider’s words | Relevant application question | Possible experience | Evidence gap |\n|---|---|---|---|\n| `[Copy exactly]` | `[Copy or identify question]` | `[Write here]` | `[Write here]` |\n| `[Copy exactly]` | `[Copy or identify question]` | `[Write here]` | `[Write here]` |\n\nDo not add leadership, innovation or community impact as criteria unless the call actually asks for them.","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]},{"id":"step-2-complete-an-evidence-card","title":"Step 2: Complete an evidence card","content":"**Criterion:** `[Copy here]`\n\n**Experience selected:** `[Project, role or decision + dates]`\n\n- What was happening? `[Write here]`\n- What needed to change or be completed? `[Write here]`\n- What were you responsible for? `[Write here]`\n- What did you decide or do? `[Describe your actions and reasoning]`\n- Who else contributed? `[Explain their part]`\n- What happened afterwards? `[Write here]`\n- Which record, output or person supports the account? `[Write here]`\n- What cannot be attributed to your work? `[Write here]`\n- What did you learn or change in your approach? `[Write here]`\n\n**Why this demonstrates the criterion:**\n\n`[Explain the connection in two sentences]`\n\n**Fictional example:** For a criterion asking about collaboration, an applicant might describe coordinating a school outreach activity with teachers and volunteers. The useful evidence would explain how they resolved competing schedules, agreed responsibilities and followed up. Merely stating that the event reached 200 pupils would leave the collaboration unexplained.","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]},{"id":"step-3-explain-why-the-fellowship-is-needed","title":"Step 3: Explain why the fellowship is needed","content":"Identify a limitation that the fellowship could help you address. Keep this separate from explaining what makes you a suitable applicant.\n\n| Current limitation or learning need | Verified fellowship component | How you would use it |\n|---|---|---|\n| `[Write here]` | `[Training, placement, mentoring or other component + source]` | `[Write here]` |\n\n**My reason for this fellowship now:** `[Write here]`","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]},{"id":"step-4-plan-a-feasible-use-afterwards","title":"Step 4: Plan a feasible use afterwards","content":"- Setting where I could use the learning: `[Write here]`\n- First action after the fellowship: `[Write here]`\n- People I would need to involve: `[Write here]`\n- Resources or permissions required: `[Write here]`\n- How I would check progress: `[Write here]`\n- What depends on others: `[Write here]`","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]},{"id":"step-5-draft-the-answer","title":"Step 5: Draft the answer","content":"Build the response around the actual question. Include enough context to understand the situation, then explain your contribution, supported result and relevant learning. Add the fellowship connection only where the question calls for it.\n\n**Draft:** `[Write here]`\n\n**Word count / permitted limit:** `[Write here]`","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]},{"id":"final-evidence-check","title":"Final evidence check","content":"- [ ] The response addresses the stated criterion and question.\n- [ ] My own decisions and actions are visible.\n- [ ] I distinguish outputs, observed outcomes and longer-term hopes.\n- [ ] The result is supported and fairly attributed.\n- [ ] My reason for the fellowship names something it actually offers.\n- [ ] My proposed use of the learning is feasible in the setting described.\n\n**Next action:** `[Write here]`\n\n---","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]}]},"content_source_version":"full-content-2026-10"}$data$::jsonb, now()),
  ($title$Build an MBA story bank$title$, $slug$build-mba-story-bank$slug$, $excerpt$Collect examples of leadership, judgement and learning before drafting essays.$excerpt$, $body$$body$, $category$MBA applications$category$, array[$tag$worksheet$tag$, $tag$mba$tag$, $tag$applications$tag$], 'published', $data${"format":"Worksheet","resource_schema":{"sections":[{"id":"how-to-use-this-worksheet","title":"How to use this worksheet","content":"Start with situations you can discuss in detail. You do not need a dramatic event or a senior job title. Keep notes on what you decided, how you worked with people and what followed. Select stories for a school only after reading its current questions.","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]},{"id":"step-1-collect-possible-stories","title":"Step 1: Collect possible stories","content":"Try to identify examples for the first four categories. One experience may fit several categories, but it should still answer the chosen prompt directly.\n\n| Story category | Situation and date | Your responsibility | Why it may be useful |\n|---|---|---|---|\n| A decision with a trade-off | `[Write here]` | `[Write here]` | `[Write here]` |\n| Working through disagreement | `[Write here]` | `[Write here]` | `[Write here]` |\n| Responsibility and results | `[Write here]` | `[Write here]` | `[Write here]` |\n| A setback or mistake | `[Write here]` | `[Write here]` | `[Write here]` |\n| Another experience relevant to a school’s question | `[Write here]` | `[Write here]` | `[Write here]` |","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]},{"id":"step-2-complete-a-story-card","title":"Step 2: Complete a story card","content":"Duplicate this card for each experience you want to develop.\n\n**Story name and date:** `[Write here]`\n\n- Context: `[What was happening, and who was involved?]`\n- Stakes: `[What could be gained, lost or left unresolved?]`\n- Your responsibility: `[What did you own?]`\n- Options: `[Which realistic alternatives did you consider?]`\n- Decision and reasoning: `[What did you choose, and why?]`\n- Actions: `[What did you personally do?]`\n- Other people’s contributions: `[Write here]`\n- Result: `[What happened, with evidence where available?]`\n- Limits: `[What was outside your control or remains unresolved?]`\n- Learning: `[What did you change in later work?]`\n- Evidence or possible referee: `[Record, output or person]`\n\n**Fictional story note:** A project lead could choose to postpone a launch after finding an unresolved quality issue. A useful account would explain the competing pressures, how the lead assessed the risk, who disagreed, the communication with the client and the eventual outcome. Calling the decision “bold leadership” would add little without those details.\n\nFor a setback, name your part in the mistake. Explain the correction and what happened afterwards without turning every difficulty into an unsupported success claim.","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]},{"id":"step-3-connect-the-stories-to-your-career-direction","title":"Step 3: Connect the stories to your career direction","content":"- Current role and relevant preparation: `[Write here]`\n- Intended role, sector or business direction after the MBA: `[Write here]`\n- Why that next step follows from your experience: `[Write here]`\n- Skills or exposure you still need: `[Write here]`\n- Assumptions to check about the target role or market: `[Write here]`\n- Alternative next step if the first route is unavailable: `[Write here]`\n\n**My career direction in three sentences:**\n\n`[Write here]`","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]},{"id":"step-4-research-school-specific-fit","title":"Step 4: Research school-specific fit","content":"| Learning need | Verified school feature | How you would use it | Official source and date |\n|---|---|---|---|\n| `[Write here]` | `[Course, project, centre or other feature]` | `[Write here]` | `[Link + date]` |\n\nCheck access and availability. Do not imply that admission guarantees a place in a particular elective, project, club leadership role or job.","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]},{"id":"step-5-allocate-stories-to-actual-prompts","title":"Step 5: Allocate stories to actual prompts","content":"| School and exact question | Limit | Story or evidence selected | Why it answers this question |\n|---|---|---|---|\n| `[Write here]` | `[Words / characters / other format]` | `[Story name]` | `[Write here]` |\n| `[Write here]` | `[Write here]` | `[Story name]` | `[Write here]` |\n\nReview all answers for the same school together. Avoid repeating the same account when another experience would show something the reader has not seen. You can adapt a genuine story for another school, but reassess it against that school’s prompt.","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]},{"id":"step-6-prepare-for-follow-up-questions","title":"Step 6: Prepare for follow-up questions","content":"For each selected story, practise answering:\n\n- Why did you choose that option?\n- What did another team member contribute?\n- How do you know the result followed?\n- What would you do differently now?\n\n**Details I need to check before drafting:** `[Write here]`\n\n**Story to develop first and why:** `[Write here]`\n\n[Explore MBA support](https://careergrill-website-concept.sannialausa.chatgpt.site/services?section=pricing&category=mba)\n\n---","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]}]},"content_source_version":"full-content-2026-10"}$data$::jsonb, now()),
  ($title$Prepare a useful brief for your referee$title$, $slug$prepare-brief-for-referee$slug$, $excerpt$Give your referee the context, evidence and submission details they need.$excerpt$, $body$$body$, $category$Graduate admissions$category$, array[$tag$template$tag$, $tag$graduate$tag$, $tag$admissions$tag$], 'published', $data${"format":"Template","resource_schema":{"sections":[{"id":"how-to-use-this-template","title":"How to use this template","content":"Ask if the person is willing and able to provide the reference before sending a full brief. Choose someone who meets the provider’s requirements and can discuss relevant work they know. The referee should make their own assessment; your brief supplies context and factual reminders.","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]},{"id":"step-1-confirm-agreement-and-suitability","title":"Step 1: Confirm agreement and suitability","content":"- Referee’s name and role: `[Write here]`\n- How you worked or studied together: `[Write here]`\n- Dates of that relationship: `[Write here]`\n- Provider’s referee requirements: `[Copy requirement + official link]`\n- Agreement received on: `[Date]`\n- Reminder date agreed: `[Date]`\n\nIf agreement has not been received, ask first:\n\n> Dear [Name],\n>\n> I’m applying for [programme/award] at [institution]. Would you be willing to provide a reference based on our work together on [course/project/role]?\n>\n> The reference is due on [date, time and time zone] and is submitted through [route]. I can send the official requirements, my CV and a short summary of the work you observed. Please let me know if the timeline works for you.\n>\n> Thank you,\n> [Your name]","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]},{"id":"step-2-complete-the-referee-brief","title":"Step 2: Complete the referee brief","content":"#### Opportunity\n\n- Programme or award and institution: `[Write here]`\n- Why I am applying: `[Two or three sentences]`\n- Official reference instructions: `[Paste link or attach instructions]`\n- Qualities or questions the reference must address: `[Copy the provider’s wording]`\n\n#### Our shared work\n\n- Course, project or role: `[Write here]`\n- Dates and responsibilities: `[Write here]`\n- How closely we worked together: `[Write here]`\n\n#### Examples you directly observed\n\n| Work or situation | My contribution | Output or outcome | Factual reminder / useful record |\n|---|---|---|---|\n| `[Write here]` | `[Write here]` | `[Write here]` | `[Write here]` |\n| `[Write here]` | `[Write here]` | `[Write here]` | `[Write here]` |\n\nInclude facts the referee can check. Do not ask them to describe work they did not observe or adopt an assessment you have written for them.\n\n#### Supporting materials\n\n- Current CV: `[File name / link]`\n- Application goals or statement, if useful: `[File name / link]`\n- Relevant work sample or record: `[File name / link]`\n- Required reference form or questions: `[File name / link]`\n\nSend only materials that are relevant and appropriate to share.\n\n#### Submission instructions\n\n- Deadline, time and time zone: `[Write here]`\n- Submission route: `[Portal invitation / email / other official route]`\n- When and how the invitation will arrive: `[Write here]`\n- Required format, length or questions: `[Write here]`\n- Confidentiality / applicant-access instructions: `[Copy official guidance]`\n- Applicant or application identifier, if needed: `[Write here]`\n- Official contact for submission problems: `[Write here]`","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]},{"id":"step-3-send-the-agreed-brief","title":"Step 3: Send the agreed brief","content":"> Dear [Name],\n>\n> Thank you for agreeing to provide a reference for my application to [programme/award]. I’ve attached [materials] and included the submission instructions below.\n>\n> The reference is due on [date, time and time zone]. [Explain the confirmed submission route and any action needed.]\n>\n> For context, I worked with you on [shared work] during [dates]. The brief includes factual reminders of [examples] that you observed. Please use your own judgement about what is relevant to your assessment.\n>\n> We agreed that I would check in on [reminder date]. Let me know if you need anything else from me.\n>\n> Thank you,\n> [Your name]","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]},{"id":"step-4-follow-up-and-confirm-receipt","title":"Step 4: Follow up and confirm receipt","content":"**Optional reminder:**\n\n> Dear [Name],\n>\n> As agreed, I’m checking in about the reference for [programme/award], due on [date, time and time zone]. The portal currently shows [actual status]. Please let me know if you need the invitation or instructions resent through the official process.\n>\n> Thank you,\n> [Your name]\n\n- [ ] Agreement is confirmed.\n- [ ] The brief, materials and instructions have been sent.\n- [ ] Any portal invitation has been issued and the referee can access it.\n- [ ] Receipt has been checked through the official route.\n- [ ] I have thanked the referee and will share the application outcome when known.\n\n**Submission status and date checked:** `[Write here]`\n\n---","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]}]},"content_source_version":"full-content-2026-10"}$data$::jsonb, now()),
  ($title$Check your preparation for a PhD application$title$, $slug$phd-application-preparation-checklist$slug$, $excerpt$Connect your research question to supervision, methods and funding requirements.$excerpt$, $body$$body$, $category$Graduate admissions$category$, array[$tag$checklist$tag$, $tag$graduate$tag$, $tag$admissions$tag$], 'published', $data${"format":"Checklist","resource_schema":{"sections":[{"id":"how-to-use-this-checklist","title":"How to use this checklist","content":"Use the programme’s current instructions. Some routes involve a proposed research project and supervisor contact; others recruit to a defined project or make supervision arrangements later. Mark checks as complete only when you have evidence, and use the unresolved questions to plan your next conversation.","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]},{"id":"application-details","title":"Application details","content":"- Programme / advertised project and institution: `[Write here]`\n- Official application instructions: `[Paste link]`\n- Department and funding information: `[Paste links]`\n- Application and funding deadlines: `[Dates, times and time zones]`\n- Date checked: `[Write here]`","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]},{"id":"check-1-can-you-describe-your-research-direction","title":"Check 1: Can you describe your research direction?","content":"- Broad area: `[Write here]`\n- Specific question or problem: `[Write here]`\n- Work, reading or experience that led to it: `[Write here]`\n- What existing research helps you understand: `[Name relevant work and its contribution]`\n- What remains uncertain or worth investigating: `[Write here]`\n\n**Working research question:**\n\n`[Write here]`\n\n- [ ] I can explain the question in plain language.\n- [ ] I distinguish what I know from what I need to investigate.\n- [ ] The question matches the advertised project or route, where applicable.","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]},{"id":"check-2-what-preparation-can-you-demonstrate","title":"Check 2: What preparation can you demonstrate?","content":"| Experience or skill | What you actually did | Evidence | Preparation still needed |\n|---|---|---|---|\n| Research project / dissertation | `[Write here]` | `[Output, report or record]` | `[Write here]` |\n| Methods or analytical training | `[Write here]` | `[Coursework, project or other evidence]` | `[Write here]` |\n| Relevant professional or field experience | `[Write here]` | `[Write here]` | `[Write here]` |\n\n- [ ] I have checked the programme’s qualification and other entry requirements.\n- [ ] I can explain my research role, methods and findings accurately.\n- [ ] I have identified skill gaps without treating every gap as automatic ineligibility.\n\nCheck the route’s actual requirements rather than assuming that every PhD requires the same qualifications, publications or prior methods training.","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]},{"id":"check-3-is-there-supervision-and-department-fit","title":"Check 3: Is there supervision and department fit?","content":"| Potential supervisor / group / project | Relevant research you have read | Connection to your question | Official contact or capacity information |\n|---|---|---|---|\n| `[Write here]` | `[Publication / project + link]` | `[Write here]` | `[Write here, or Unconfirmed]` |\n\n- [ ] I have read the instructions on contacting supervisors.\n- [ ] I have checked current staff profiles and relevant research.\n- [ ] I have checked any advertised availability or project restrictions.\n- [ ] I understand that a positive conversation does not itself confirm admission or funding.\n\n**Question I would ask about fit:** `[Write here]`","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]},{"id":"check-4-what-does-the-proposal-or-project-statement-require","title":"Check 4: What does the proposal or project statement require?","content":"- Required document and length: `[Write here]`\n- Required sections or questions: `[Copy here]`\n- Proposal required at this stage: `[Confirmed requirement]`\n- Research design or methods to explain: `[Write here]`\n- Data, participants, materials or facilities needed: `[Write here]`\n- Access, permissions, ethics or feasibility questions: `[Write here]`\n- Required supporting documents: `[Write here]`\n\n- [ ] I distinguish an exploratory idea from a submission-ready proposal.\n- [ ] The proposed work is proportionate to the route and resources described.\n- [ ] I have followed any instructions for an advertised project rather than substituting an unrelated proposal.","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]},{"id":"check-5-have-you-checked-the-funding-route","title":"Check 5: Have you checked the funding route?","content":"| Funding question | Confirmed answer | Official source / action |\n|---|---|---|\n| Fees covered and any fee-category restrictions | `[Write here]` | `[Write here]` |\n| Stipend amount, duration and start date | `[Write here]` | `[Write here]` |\n| Nationality or residence conditions | `[Write here]` | `[Write here]` |\n| Separate application or nomination needed | `[Write here]` | `[Write here]` |\n| Teaching/research duties, if part of the funding | `[Write here]` | `[Write here]` |\n| Research, travel or other costs outside the award | `[Write here]` | `[Write here]` |\n\n- [ ] I have checked admission and funding conditions separately.\n- [ ] I have recorded every relevant deadline.\n- [ ] I have identified any gap between the funding period and proposed study period.\n\nUse Resource 2 to examine the full cost coverage if a funding offer is involved.","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]},{"id":"check-6-what-needs-to-be-resolved-before-submission","title":"Check 6: What needs to be resolved before submission?","content":"| Unresolved question | Who can answer it? | Action and date |\n|---|---|---|\n| `[Write here]` | `[Department / admissions / funding office / other]` | `[Write here]` |\n| `[Write here]` | `[Write here]` | `[Write here]` |\n\n**My next step:** `[Further reading / Confirm requirements / Ask about supervision / Develop proposal / Request feedback / Complete submission checks]`\n\n**What I will complete before that step:** `[Write here]`\n\n**Date:** `[Write here]`\n\nCompleting this checklist helps you identify what is ready and what needs attention. It does not confirm eligibility, supervision or funding; those decisions sit with the institution and provider.","fields":[{"id":"notes","label":"Your notes","type":"textarea","placeholder":"Record your answer, evidence or next action."}]}]},"content_source_version":"full-content-2026-10"}$data$::jsonb, now())
on conflict (slug) do update set
  title = excluded.title,
  excerpt = excluded.excerpt,
  body = excluded.body,
  category = excluded.category,
  tags = excluded.tags,
  status = excluded.status,
  published_at = coalesce(public.resources.published_at, excluded.published_at),
  data = coalesce(public.resources.data, '{}'::jsonb) || excluded.data,
  updated_at = now()
where public.resources.data->>'content_source_version' is distinct from 'full-content-2026-10';
